.chat-container {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Left Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background-color: #1a1d21;
    color: #ccc;
